params.command:
$ErrorActionPreference='Stop'
$baseline='C:\Users\Xxkan\mhw-perf-v8814-baseline'
$candidate='C:\Users\Xxkan\mhw-perf-v8814-candidate'
foreach($p in @($baseline,$candidate)){
  if(Test-Path -LiteralPath $p){Remove-Item -LiteralPath $p -Recurse -Force}
}
git clone --quiet --branch main --single-branch https://github.com/fengie/mhw-mods.git $baseline
if($LASTEXITCODE -ne 0){throw 'baseline clone failed'}
git clone --quiet --branch perf-startup-20260929 --single-branch https://github.com/fengie/mhw-mods.git $candidate
if($LASTEXITCODE -ne 0){throw 'candidate clone failed'}

$baselineSha=(git -C $baseline rev-parse HEAD).Trim()
$candidateSha=(git -C $candidate rev-parse HEAD).Trim()
Write-Output "BASELINE_SHA=$baselineSha"
Write-Output "CANDIDATE_SHA=$candidateSha"
Write-Output ("DOTNET=" + (& dotnet --version).Trim())

dotnet restore "$baseline\src\MhwModManager.App\MhwModManager.App.csproj" -p:NuGetAudit=false
if($LASTEXITCODE -ne 0){throw 'baseline restore failed'}
dotnet build "$baseline\src\MhwModManager.App\MhwModManager.App.csproj" -c Release --no-restore -p:NuGetAudit=false
if($LASTEXITCODE -ne 0){throw 'baseline build failed'}

dotnet restore "$candidate\src\MhwModManager.App\MhwModManager.App.csproj" -p:NuGetAudit=false
if($LASTEXITCODE -ne 0){throw 'candidate restore failed'}
dotnet build "$candidate\src\MhwModManager.App\MhwModManager.App.csproj" -c Release --no-restore -p:NuGetAudit=false
if($LASTEXITCODE -ne 0){throw 'candidate build failed'}

& "$candidate\scripts\Measure-StartupPerformance.ps1" -RepositoryRoot $baseline -OutputPath 'BuildLogs\startup-performance-baseline.json' -ColdIterations 3 -WarmIterations 3 -ModCount 80 -FilesPerMod 25 -TimeoutSeconds 120
if($LASTEXITCODE -ne 0){throw 'baseline benchmark failed'}
& "$candidate\scripts\Measure-StartupPerformance.ps1" -RepositoryRoot $candidate -OutputPath 'BuildLogs\startup-performance-candidate.json' -ColdIterations 3 -WarmIterations 3 -ModCount 80 -FilesPerMod 25 -TimeoutSeconds 120
if($LASTEXITCODE -ne 0){throw 'candidate benchmark failed'}

dotnet test "$candidate\tests\MhwModManager.IntegrationTests\MhwModManager.IntegrationTests.csproj" -c Release -p:NuGetAudit=false --filter "FullyQualifiedName~DebugTraceCoverageTests|FullyQualifiedName~HiddenSecondaryPagesAreLazyLoadedAfterStartup"
if($LASTEXITCODE -ne 0){throw 'startup guard tests failed'}
python "$candidate\plugins\verify.py"
if($LASTEXITCODE -ne 0){throw 'plugin gate failed'}

$b=Get-Content -LiteralPath "$baseline\BuildLogs\startup-performance-baseline.json" -Raw | ConvertFrom-Json
$c=Get-Content -LiteralPath "$candidate\BuildLogs\startup-performance-candidate.json" -Raw | ConvertFrom-Json
$metrics=@('process_to_ready_ms','session_to_main_window_show_ms','session_to_ready_ms','cpu_ms','peak_working_set_mb','idle_working_set_mb','catalog_refresh_ms','main_window_initialize_ms','master_log_mb')
$out=[ordered]@{
 baseline_sha=$b.source_sha
 candidate_sha=$c.source_sha
 package_size_mb=[ordered]@{before=$b.package_size_mb;after=$c.package_size_mb}
 cold=[ordered]@{}
 warm=[ordered]@{}
}
foreach($m in $metrics){
 $out.cold[$m]=[ordered]@{before=$b.cold.$m;after=$c.cold.$m}
 $out.warm[$m]=[ordered]@{before=$b.warm.$m;after=$c.warm.$m}
}
Write-Output 'PERF_COMPARISON_JSON_BEGIN'
Write-Output ($out | ConvertTo-Json -Depth 8 -Compress)
Write-Output 'PERF_COMPARISON_JSON_END'
